"""Generated files: the index (brain/README.md), one README.md per type folder (the concepts' is the glossary, the
features' the catalogue), context packs, backlinks. Date-independent: retention lives in retention.py."""
import json
import posixpath
import re

from . import links
from .brain import CONTEXT, CONTROL, INDEX
from .context import SECTIONS, build_context, summary_of

HEADER = "<!-- generated by pb; do not edit -->"
LANGUAGES = {"en": "English", "it": "Italian", "de": "German", "fr": "French", "es": "Spanish"}
CLOSED = {"decision": {"superseded"}, "open-question": {"resolved", "dropped"}}
GROUPS = [("functional", "Functional"), ("technical", "Technical"), (None, "Decisions and questions")]
_ORDER = {t: i for i, (t, _) in enumerate(SECTIONS)}


def generate(brain):
    written, deleted = [], []

    def write(rel, text):
        path = brain.root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.is_file() or path.read_text(encoding="utf-8") != text:
            path.write_text(text, encoding="utf-8")
        written.append(rel)

    pages = [p for p in brain.pages() if p.type in brain.types]
    write(INDEX, _index(brain))
    for typedef in sorted(brain.types.values(), key=lambda t: t.folder):
        if typedef.folder:
            write(f"{typedef.folder}/{INDEX}", _folder_readme(brain, typedef, pages))
    write(f"{CONTROL}/backlinks.json",
          json.dumps(_backlinks(brain, pages), indent=2, sort_keys=True, ensure_ascii=False) + "\n")

    packs = {f"{p.title}.md": p for p in pages if p.type == "feature"}
    for name, p in sorted(packs.items()):
        write(f"{CONTEXT}/{name}", build_context(brain, feature=p.title)["markdown"])
    ctx = brain.root / CONTEXT
    for path in sorted(ctx.glob("*.md")) if ctx.is_dir() else []:
        if path.name not in packs:
            path.unlink()
            deleted.append(f"{CONTEXT}/{path.name}")
    return {"written": written, "deleted": deleted}


def is_archived(page):
    """Archived pages are flagged by retention (`archived: true`); generation never decides by date."""
    return page.get("archived") is True


SENTENCE_END = re.compile(r"(?<!e\.g\.)(?<!i\.e\.)(?<=[.!?])\s")


def _visible(m):
    """The text a link shows: its label (a wikilink: the label, else the title)."""
    if m.group("wtarget") is not None:
        target, _, label = links._wiki_parts(m)
        return label or target
    return m.group("label")


def _first_sentence(text, limit=120):
    """The first sentence of text, cut at `limit` characters of visible text (link labels, not their targets),
    never inside a link."""
    text = (text or "").strip()
    out, used, pos = [], 0, 0
    pieces = []
    for m in links.TOKEN.finditer(text):
        pieces += [(text[pos:m.start()], None), (m.group(0), m)]
        pos = m.end()
    pieces.append((text[pos:], None))
    for raw, m in pieces:
        if m is not None:
            shown = len(_visible(m))
            if used + shown > limit:
                return "".join(out).rstrip() + "…"
            out.append(raw)
            used += shown
            continue
        end = SENTENCE_END.search(raw)
        chunk = raw[:end.start()] if end else raw
        if used + len(chunk) > limit:
            return "".join(out) + chunk[:max(limit - used - 1, 0)].rstrip() + "…"
        out.append(chunk)
        used += len(chunk)
        if end:
            break
    return "".join(out)


def _heading(folder):
    name = folder.rstrip("/").split("/")[-1].replace("-", " ")
    return name[:1].upper() + name[1:]


def describe(typedef):
    """The type's one-line description: the first sentence of its prose."""
    for block in (typedef.prose or "").split("\n\n"):
        lines = [l.strip() for l in block.strip().splitlines() if l.strip() and not l.lstrip().startswith("#")]
        if lines:
            return _first_sentence(" ".join(lines), 1000)
    return ""


def _summary(brain, page, folder, limit=120):
    """The page's summary in one sentence, its links valid from `folder`."""
    return links.rewrite(brain, _first_sentence(summary_of(page), limit), posixpath.dirname(page.rel), folder)


def _link(brain, page, folder):
    return f"[{_cell(page.title)}]({links.href(page.rel, folder)})"


def _index(brain):
    """brain/README.md: one line per type folder of the schema, no pages, so it changes only with the schema."""
    product = brain.config.get("product") or "Product"
    out = [HEADER, f"# {product} brain", "",
           f"The product knowledge of {product} for people and AI agents: what the product does and why, what the "
           "code cannot say about how it is built, the decisions taken and the questions still open.",
           "Pages change with the code in working branches, through the `pb` Claude plugin; agents follow "
           "[AGENTS.md](AGENTS.md).", ""]
    groups = {}
    for t in brain.types.values():
        if t.folder:
            area = t.area if t.area in ("functional", "technical") else None
            groups.setdefault(area, []).append(t)
    for area, title in GROUPS:
        types = sorted(groups.get(area, []), key=lambda t: (_ORDER.get(t.name, 99), t.folder))
        if not types:
            continue
        out += [f"## {title}", ""]
        for t in types:
            line = f"- [{_heading(t.folder)}]({links.href(t.folder + '/' + INDEX, '')})"
            description = describe(t)
            out.append(line + (f" — {description}" if description else ""))
        out.append("")
    return "\n".join(out).rstrip() + "\n"


def _intro(brain, typedef, heading):
    up = links.href(INDEX, typedef.folder)
    description = describe(typedef)
    return [HEADER, f"# {heading}", "", (description + " " if description else "") + f"[Brain index]({up})", ""]


def _folder_readme(brain, typedef, pages):
    mine = [p for p in pages if p.type == typedef.name]
    listed = [p for p in mine if not is_archived(p)]
    if typedef.name == "concept":
        out = _glossary(brain, typedef, listed)
    elif typedef.name == "feature":
        out = _features(brain, typedef, listed)
    else:
        out = _intro(brain, typedef, _heading(typedef.folder))
        for p in sorted(listed, key=lambda p: p.title.lower()):
            line = f"- {_link(brain, p, typedef.folder)}"
            notes = _notes(p)
            if notes:
                line += f" ({', '.join(notes)})"
            summary = _summary(brain, p, typedef.folder)
            out.append(line + (f" — {summary}" if summary else ""))
        if not listed:
            out.append("_none yet_")
        out.append("")
    archived = len(mine) - len(listed)
    if archived:
        out += [f"Archived: {archived} pages (not listed).", ""]
    return "\n".join(out).rstrip() + "\n"


def _notes(page):
    """Decisions show status and date; open questions their area (and their status once closed)."""
    if page.type == "decision":
        return [str(v) for v in (page.get("status"), page.get("date")) if v]
    if page.type == "open-question":
        status = page.get("status")
        return [str(v) for v in (page.get("area"), status if status and status != "open" else None) if v]
    if page.type in CLOSED and page.get("status"):
        return [str(page.get("status"))]
    return []


def _cell(text):
    return str(text).replace("|", "\\|").replace("\n", " ")


def _glossary(brain, typedef, concepts):
    langs = brain.config.get("glossary_languages") or ["en"]
    names = [LANGUAGES.get(l, l) for l in langs]
    out = _intro(brain, typedef, "Glossary")
    if not concepts:
        return out + ["_none yet_", ""]
    out += ["| " + " | ".join(names + ["Definition"]) + " |", "|" + "---|" * (len(names) + 1)]
    for p in sorted(concepts, key=lambda p: str(p.get(f"term_{langs[0]}") or p.title).lower()):
        cells = []
        for i, lang in enumerate(langs):
            term = p.get(f"term_{lang}")
            if i == 0:
                cells.append(f"[{_cell(term or p.title)}]({links.href(p.rel, typedef.folder)})")
            else:
                cells.append(_cell(term) if term else "—")
        cells.append(_cell(_summary(brain, p, typedef.folder, 200)))
        out.append("| " + " | ".join(cells) + " |")
    return out + [""]


STATUS_ORDER = ["released", "in-progress", "planned", "idea", "deprecated"]
UNCATEGORISED = "Uncategorised"


def _features(brain, typedef, features):
    """Feature catalogue: features grouped by capability, then by status."""
    product = brain.config.get("product") or "Product"
    out = _intro(brain, typedef, f"{product} features")
    groups = {}
    for p in features:
        groups.setdefault(str(p.get("capability") or "").strip() or UNCATEGORISED, []).append(p)
    if not groups:
        return out + ["_none yet_", ""]
    rank = {s: i for i, s in enumerate(STATUS_ORDER)}

    def roles(p):
        cells = []
        for _, title in links.meta_links({"roles": p.get("roles")}, typedef):
            found, _ = brain.lookup(title)
            cells.append(_link(brain, found, typedef.folder) if found is not None else _cell(title))
        return ", ".join(cells)

    names = sorted((g for g in groups if g != UNCATEGORISED), key=str.lower)
    for name in names + ([UNCATEGORISED] if UNCATEGORISED in groups else []):
        out += [f"## {name}", "", "| Feature | Status | Roles | Summary |", "|---|---|---|---|"]
        for p in sorted(groups[name], key=lambda p: (rank.get(p.get("status") or "idea", 99), p.title.lower())):
            out.append(f"| {_link(brain, p, typedef.folder)} | {p.get('status') or 'idea'} | {roles(p) or '—'} | "
                       f"{_cell(_summary(brain, p, typedef.folder, 160))} |")
        out.append("")
    return out


def _backlinks(brain, pages):
    result = {}
    for p in pages:
        targets = [r.page for r in links.refs(brain, p.rel, p.body)]
        targets += [brain.lookup(t)[0] for _, t in links.meta_links(p.meta, brain.types.get(p.type))]
        for found in set(t for t in targets if t is not None):
            if found.title != p.title:
                result.setdefault(found.title, set()).add(p.title)
    return {k: sorted(v) for k, v in result.items()}
